    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le texte de la page 23 atteste l’avis de motion du règlement 437-2026 concernant la transmission des demandes de dérogation mineure."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "La résolution 2026-03-080 adopte le premier projet du règlement 437-2026 à la page 23, distinctement de l’avis de motion."
