    {
      "item": "i12",
      "choice": "v1",
      "reason": "La résolution 2026-03-081, page 23, fixe la consultation publique concernant le règlement 437-2026 au 23 mars 2026 à 18h10."
    },
    {
      "item": "i13",
      "choice": "v1",
      "reason": "À la page 24, Jacques Tessier donne expressément avis de motion du règlement 438-2026 concernant les dispositions relatives aux autres permis."
    },
    {
      "item": "i14",
      "choice": "v1",
      "reason": "À la page 24, Jacques Tessier dépose explicitement le projet de règlement 438-2026, fait distinct de l’avis de motion."
    },
    {
      "item": "i15",
      "choice": "v1",
      "reason": "La page 25 atteste l’appui à une demande de suspension des nouvelles activités dans le périmètre PR-1013718 jusqu’à une décision gouvernementale, et non une protection déjà acquise."
    },
    {
      "item": "i16",
      "choice": "v1",
      "reason": "À la page 25, Frédéric Lapointe donne avis de motion du règlement 440-2026 visant la zone 96-Rc et l’ajout d’une définition de conteneur."
    },
    {
      "item": "i17",
      "choice": "v1",
      "reason": "La résolution 2026-03-083 adopte explicitement le premier projet du règlement 440-2026 à la page 26."
    },
    {
      "item": "i18",
      "choice": "v1",
      "reason": "La résolution 2026-03-084, page 26, fixe la consultation publique concernant le règlement 440-2026 au 23 mars 2026 à 18h15."
    },
    {
      "item": "i19",
      "choice": "v1",
      "reason": "La résolution 2026-03-085, page 26, appuie la demande à la CPTAQ pour l’acquisition d’environ 4,6 acres du lot 4 756 274, sans constater l’autorisation de la CPTAQ ni l’acquisition."
    },
    {
      "item": "i20",
      "choice": "v1",
      "reason": "La résolution 2026-03-086, page 27, accepte la dérogation du 250-252, rue Notre-Dame pour une largeur de lot de 13,72 mètres, une marge latérale de 4 mètres et une somme des marges latérales de 6 mètres."
    },
    {
      "item": "i21",
      "choice": "v1",
      "reason": "La résolution 2026-03-087, page 27, refuse le dépassement de superficie du garage au 500, rue Bédard, mais autorise une marge gauche de 1,25 mètre sans fenêtres ni portes vers cette limite."
    }
  ]
